// Types and helpers for web/public/data/products.json (generated by tools/export_products.py from peaksure/products.py).
export type Status = "CONFIRMED" | "REON CLAIM" | "DERIVED" | "LITERATURE" | "ASSUMED" | "UNKNOWN" | "MODEL OUTPUT";
export interface Spec { value: unknown; status: Status; source: string; note: string }
export interface ProductProfile { key: string; name: string; role: string; specs: Record<string, Spec> }
export interface ProductsFile {
  checked: string; statuses: Status[]; sources: Record<string, string>;
  use_case: { modelled: string; status: Status; note: string; not_modelled: string[] };
  products: ProductProfile[]; model: ProductProfile;
}

export const PARAM_LABELS: Record<string, string> = {
  rated_power_kw: "Rated power (kW)", rated_energy_kwh: "Rated energy (kWh)", energy_basis: "Energy basis",
  ac_interface: "AC interface", dc_window_v: "DC voltage window", chemistry: "Chemistry", cell_format: "Cell format",
  cells_per_string: "Cells per string", parallel_columns: "Parallel strings / columns", n_min: "N_min",
  switch_r_on: "Switch R_on", round_trip_eff: "Efficiency", cell_level_bypass: "Cell-level bypass",
};

export const specText = (s?: Spec) => (!s || s.value === null || s.value === undefined ? "—" : typeof s.value === "boolean" ? (s.value ? "yes" : "no") : String(s.value));
